//! About dialog: version, license, and the third-party notices generated by
//! `build.rs` (every linked crate and its license texts).

use std::sync::OnceLock;

use gpui_kit::component::WindowExt as _;
use gpui_kit::component::button::Button;
use gpui_kit::prelude::*;
use gpui_kit::{App, FontWeight, Window, div, px, uniform_list};

use crate::theme::Palette;

/// This project's own notice (copyright, bundled data) followed by the
/// generated per-crate notices.
const PROJECT_NOTICE: &str = include_str!("../../../../NOTICE");
const CRATE_NOTICES: &str = include_str!(concat!(env!("OUT_DIR"), "/notices.txt"));
const REPOSITORY: &str = env!("CARGO_PKG_REPOSITORY");

/// Rows are a fixed height in the notices list, so long lines are wrapped
/// up front.
const WRAP: usize = 100;

fn notice_lines() -> &'static [String] {
    static LINES: OnceLock<Vec<String>> = OnceLock::new();
    LINES.get_or_init(|| {
        let mut lines = Vec::new();
        for line in PROJECT_NOTICE.lines().chain(std::iter::once("")).chain(CRATE_NOTICES.lines()) {
            let chars: Vec<char> = line.chars().collect();
            if chars.is_empty() {
                lines.push(String::new());
            }
            for chunk in chars.chunks(WRAP) {
                lines.push(chunk.iter().collect());
            }
        }
        lines
    })
}

/// From the menu: does nothing while another dialog is up.
pub fn open(window: &mut Window, cx: &mut App) {
    if !window.has_active_dialog(cx) {
        show(window, cx);
    }
}

/// Opens on top of whatever dialog is showing (e.g. from Settings).
pub fn show(window: &mut Window, cx: &mut App) {
    window.open_dialog(cx, |dialog, _, cx| {
        let palette = Palette::get(cx);
        let source = format!("Source code: {REPOSITORY}");
        dialog.title("About Signal GPUI").w(px(440.)).child(
            div()
                .flex()
                .flex_col()
                .gap_3()
                .text_sm()
                .child(
                    div()
                        .flex()
                        .flex_col()
                        .child(div().text_lg().font_weight(FontWeight::SEMIBOLD).child("Signal GPUI"))
                        .child(
                            div()
                                .text_color(palette.text_secondary)
                                .child(format!("Version {}", env!("CARGO_PKG_VERSION"))),
                        ),
                )
                .child(div().child(env!("CARGO_PKG_DESCRIPTION")))
                .child(div().text_color(palette.text_secondary).child(
                    "An unofficial client, not affiliated with or endorsed by Signal Messenger LLC or the \
                     Signal Technology Foundation.",
                ))
                .child(div().child(
                    "Free software under the GNU Affero General Public License, version 3 only. You may \
                     redistribute and modify it under those terms; it comes with no warranty.",
                ))
                .child(
                    div()
                        .id("source-link")
                        .text_color(palette.accent)
                        .underline()
                        .cursor_pointer()
                        .on_click(|_, _, cx| cx.open_url(REPOSITORY))
                        .child(source),
                )
                .child(
                    div().child(
                        Button::new("third-party-notices")
                            .label("Third-party notices…")
                            .on_click(|_, window, cx| open_notices(window, cx)),
                    ),
                ),
        )
    });
}

fn open_notices(window: &mut Window, cx: &mut App) {
    window.open_dialog(cx, |dialog, _, cx| {
        let palette = Palette::get(cx);
        let lines = notice_lines();
        dialog.title("Third-party notices").w(px(760.)).child(
            uniform_list("notices", lines.len(), move |range, _, _| {
                range
                    .map(|ix| {
                        div()
                            .h(px(16.))
                            .text_xs()
                            .whitespace_nowrap()
                            .text_color(palette.text)
                            .child(lines[ix].clone())
                    })
                    .collect()
            })
            .h(px(480.)),
        )
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn notices_cover_the_signal_libraries_and_wrap() {
        let lines = notice_lines();
        let text = lines.join("\n");
        for needle in ["libsignal-protocol", "presage", "mozjpeg-sys", "GNU AFFERO GENERAL PUBLIC LICENSE", "Independent JPEG Group"] {
            assert!(text.contains(needle), "missing {needle}");
        }
        assert!(lines.iter().all(|l| l.chars().count() <= WRAP));
    }
}
